//! TLS (`rediss://`) connections, with the `tls` feature: a real TLS `redis-server` with
//! certificates generated by `openssl` for each test.
#![cfg(feature = "tls")]

mod common;

use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

use hench::prelude::*;
use hench::{Error, RedisConfig, TlsConfig};

/// A TCP server that accepts connections and closes them without speaking TLS.
async fn plain_tcp_server() -> u16 {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    tokio::spawn(async move {
        while let Ok((socket, _)) = listener.accept().await {
            drop(socket);
        }
    });
    port
}

#[tokio::test]
async fn tls_connections_fail_cleanly_instead_of_panicking() {
    let port = plain_tcp_server().await;
    let config = RedisConfig::new(format!("rediss://127.0.0.1:{port}"))
        .connection_timeout(Duration::from_secs(2))
        .reconnect_retries(0);
    // Building the TLS client configuration needs a rustls crypto provider; the handshake
    // then fails because the server does not speak TLS.
    let result = RedisPool::from_config(config).await;
    assert!(matches!(result, Err(Error::Redis(_))), "{result:?}");
}

/// Runs `openssl` with `args` in `dir`.
fn openssl(dir: &Path, args: &[&str]) {
    let status = Command::new("openssl")
        .args(args)
        .current_dir(dir)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .expect("the TLS tests need the `openssl` command line tool");
    assert!(status.success(), "openssl {args:?} failed");
}

/// Creates `<name>.key` and `<name>.crt` signed by the test CA.
fn issue(dir: &Path, name: &str, extensions: &str) {
    openssl(
        dir,
        &[
            "req",
            "-newkey",
            "ec",
            "-pkeyopt",
            "ec_paramgen_curve:prime256v1",
            "-nodes",
            "-keyout",
            &format!("{name}.key"),
            "-out",
            &format!("{name}.csr"),
            "-subj",
            &format!("/CN={name}"),
        ],
    );
    std::fs::write(dir.join(format!("{name}.ext")), extensions).unwrap();
    openssl(
        dir,
        &[
            "x509",
            "-req",
            "-in",
            &format!("{name}.csr"),
            "-CA",
            "ca.crt",
            "-CAkey",
            "ca.key",
            "-CAcreateserial",
            "-out",
            &format!("{name}.crt"),
            "-days",
            "2",
            "-extfile",
            &format!("{name}.ext"),
        ],
    );
}

/// The certificate a test server presents.
enum ServerCert {
    /// Signed by the test CA, with these extensions.
    Signed(&'static str),
    /// Self-signed and also a CA (what `openssl req -x509` makes by default), naming a host
    /// other than the one the tests connect to, like some managed Redis services' (Heroku).
    SelfSigned,
}

/// The extensions of the test server's usual certificate.
const LOCAL_SERVER: &str = "subjectAltName=DNS:localhost,IP:127.0.0.1\nbasicConstraints=CA:FALSE\n\
                            keyUsage=critical,digitalSignature\nextendedKeyUsage=serverAuth\n";

/// A `redis-server` listening only on a TLS port, with its certificates.
struct TlsRedis {
    dir: tempfile::TempDir,
    port: u16,
    child: Child,
}

impl TlsRedis {
    async fn start(require_client_certificates: bool) -> Self {
        Self::start_with(
            require_client_certificates,
            ServerCert::Signed(LOCAL_SERVER),
        )
        .await
    }

    async fn start_with(require_client_certificates: bool, server: ServerCert) -> Self {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path();
        openssl(
            path,
            &[
                "req",
                "-x509",
                "-newkey",
                "ec",
                "-pkeyopt",
                "ec_paramgen_curve:prime256v1",
                "-nodes",
                "-keyout",
                "ca.key",
                "-out",
                "ca.crt",
                "-days",
                "2",
                "-subj",
                "/CN=hench-test-ca",
                "-addext",
                "basicConstraints=critical,CA:TRUE",
                "-addext",
                "keyUsage=critical,keyCertSign,cRLSign",
            ],
        );
        match server {
            ServerCert::Signed(extensions) => issue(path, "server", extensions),
            ServerCert::SelfSigned => openssl(
                path,
                &[
                    "req",
                    "-x509",
                    "-newkey",
                    "ec",
                    "-pkeyopt",
                    "ec_paramgen_curve:prime256v1",
                    "-nodes",
                    "-keyout",
                    "server.key",
                    "-out",
                    "server.crt",
                    "-days",
                    "2",
                    "-subj",
                    "/CN=ec2-3-91-12-7.compute-1.amazonaws.com",
                    "-addext",
                    "subjectAltName=DNS:ec2-3-91-12-7.compute-1.amazonaws.com",
                    "-addext",
                    "basicConstraints=critical,CA:TRUE",
                ],
            ),
        }
        issue(
            path,
            "client",
            "basicConstraints=CA:FALSE\nkeyUsage=critical,digitalSignature\n\
             extendedKeyUsage=clientAuth\n",
        );

        let port = std::net::TcpListener::bind("127.0.0.1:0")
            .unwrap()
            .local_addr()
            .unwrap()
            .port();
        let child = Command::new(redis_server())
            .args([
                "--port",
                "0",
                // Also listen on ::1 when the host has IPv6 ("-" makes that
                // address optional): CI runners resolve `localhost` to ::1 first.
                "--bind",
                "127.0.0.1",
                "-::1",
                "--tls-port",
                &port.to_string(),
            ])
            .args([
                "--tls-cert-file",
                "server.crt",
                "--tls-key-file",
                "server.key",
            ])
            .args(["--tls-ca-cert-file", "ca.crt"])
            .args([
                "--tls-auth-clients",
                if require_client_certificates {
                    "yes"
                } else {
                    "no"
                },
            ])
            .args(["--save", "", "--appendonly", "no", "--logfile", "redis.log"])
            .current_dir(path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .expect("redis-server");
        let mut redis = Self { dir, port, child };
        redis.wait_for_port().await;
        redis
    }

    async fn wait_for_port(&mut self) {
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if let Some(status) = self.child.try_wait().unwrap() {
                let log =
                    std::fs::read_to_string(self.dir.path().join("redis.log")).unwrap_or_default();
                panic!("redis-server exited ({status}); is it built with TLS? log:\n{log}");
            }
            if tokio::net::TcpStream::connect(("127.0.0.1", self.port))
                .await
                .is_ok()
            {
                return;
            }
            assert!(Instant::now() < deadline, "TLS redis-server did not start");
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    }

    fn pem(&self, file: &str) -> Vec<u8> {
        std::fs::read(self.dir.path().join(file)).unwrap()
    }

    fn config(&self, host: &str) -> RedisConfig {
        RedisConfig::new(format!("rediss://{host}:{}", self.port))
            .connection_timeout(Duration::from_secs(2))
            .reconnect_retries(0)
    }
}

impl Drop for TlsRedis {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn redis_server() -> PathBuf {
    std::env::var_os("HENCH_REDIS_SERVER").map_or_else(|| "redis-server".into(), PathBuf::from)
}

#[tokio::test]
async fn connects_with_a_custom_root_certificate() {
    let redis = TlsRedis::start(false).await;
    for host in ["localhost", "127.0.0.1"] {
        let config = redis
            .config(host)
            .tls(TlsConfig::new().root_cert(redis.pem("ca.crt")));
        let pool = RedisPool::from_config(config).await.unwrap();
        pool.ping().await.unwrap();
        let client = Client::new(pool.clone());
        client
            .push(JobPayload::new("OverTls", vec![]))
            .await
            .unwrap();
    }
    let pool = RedisPool::from_config(
        redis
            .config("localhost")
            .tls(TlsConfig::new().root_cert(redis.pem("ca.crt"))),
    )
    .await
    .unwrap();
    assert_eq!(common::queue_size(&pool, "default").await, 2);
}

#[tokio::test]
async fn rejects_servers_signed_by_an_unknown_authority() {
    let redis = TlsRedis::start(false).await;
    // The system roots do not include the test CA.
    let result = RedisPool::from_config(redis.config("localhost")).await;
    assert!(matches!(result, Err(Error::Redis(_))), "{result:?}");
}

#[tokio::test]
async fn mutual_tls() {
    let redis = TlsRedis::start(true).await;
    let anonymous = redis
        .config("localhost")
        .tls(TlsConfig::new().root_cert(redis.pem("ca.crt")));
    assert!(matches!(
        RedisPool::from_config(anonymous).await,
        Err(Error::Redis(_))
    ));

    let identified = redis.config("localhost").tls(
        TlsConfig::new()
            .root_cert(redis.pem("ca.crt"))
            .client_identity(redis.pem("client.crt"), redis.pem("client.key")),
    );
    let pool = RedisPool::from_config(identified).await.unwrap();
    pool.ping().await.unwrap();
}

/// A self-signed server certificate that is also a CA and names another host (Heroku's Redis)
/// cannot be verified, not even pinned as a root (rustls refuses a CA certificate as the
/// server's own): connecting takes an explicit opt-out, Sidekiq's `verify_mode: VERIFY_NONE`.
/// Hench had none, and redis-rs's `#insecure` URL was refused at connection time.
#[tokio::test]
async fn self_signed_servers_need_an_explicit_opt_out() {
    let redis = TlsRedis::start_with(false, ServerCert::SelfSigned).await;
    for refused in [
        redis.config("127.0.0.1"),
        redis
            .config("127.0.0.1")
            .tls(TlsConfig::new().root_cert(redis.pem("server.crt"))),
        // Accepting other host names still verifies who signed the certificate.
        redis.config("127.0.0.1").tls(
            TlsConfig::new()
                .root_cert(redis.pem("server.crt"))
                .danger_accept_invalid_hostnames(true),
        ),
    ] {
        let result = RedisPool::from_config(refused.clone()).await;
        assert!(
            matches!(result, Err(Error::Redis(_))),
            "{refused:?}: {result:?}"
        );
    }
    let unverified = redis
        .config("127.0.0.1")
        .tls(TlsConfig::new().danger_accept_invalid_certs(true));
    assert!(format!("{unverified:?}").contains("accept_invalid_certs: true"));
    let fragment = RedisConfig::new(format!("rediss://127.0.0.1:{}/#insecure", redis.port))
        .connection_timeout(Duration::from_secs(2))
        .reconnect_retries(0);
    for config in [unverified, fragment] {
        let pool = RedisPool::from_config(config).await.unwrap();
        let client = Client::new(pool.clone());
        client
            .push(JobPayload::new("OverUnverifiedTls", vec![]))
            .await
            .unwrap();
    }
    let pool = RedisPool::from_config(
        redis
            .config("127.0.0.1")
            .tls(TlsConfig::new().danger_accept_invalid_certs(true)),
    )
    .await
    .unwrap();
    assert_eq!(common::queue_size(&pool, "default").await, 2);
}

/// `danger_accept_invalid_hostnames` connects to a server whose certificate names another
/// host, as long as a trusted authority signed it.
#[tokio::test]
async fn invalid_host_names_can_be_accepted_explicitly() {
    let redis = TlsRedis::start_with(
        false,
        ServerCert::Signed(
            "subjectAltName=DNS:redis.internal\nbasicConstraints=CA:FALSE\n\
             keyUsage=critical,digitalSignature\nextendedKeyUsage=serverAuth\n",
        ),
    )
    .await;
    let pinned = TlsConfig::new().root_cert(redis.pem("ca.crt"));
    let result = RedisPool::from_config(redis.config("127.0.0.1").tls(pinned.clone())).await;
    assert!(matches!(result, Err(Error::Redis(_))), "{result:?}");
    let pool = RedisPool::from_config(
        redis
            .config("127.0.0.1")
            .tls(pinned.danger_accept_invalid_hostnames(true)),
    )
    .await
    .unwrap();
    pool.ping().await.unwrap();
    // The authority is still checked: the system roots do not include the test CA.
    let result = RedisPool::from_config(
        redis
            .config("127.0.0.1")
            .tls(TlsConfig::new().danger_accept_invalid_hostnames(true)),
    )
    .await;
    assert!(matches!(result, Err(Error::Redis(_))), "{result:?}");
}
